import { getAuthenticatedUser } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

export interface DashboardKpisResponse {
  todayBookings: number
  todayBookingsSubtext: string
  weekRevenue: number
  weekRevenueSubtext: string
  activeClients: number
  activeClientsSubtext: string
  noShowRate: number
  noShowRateSubtext: string
  depositsCollected: number
  depositsSubtext: string
  upcomingAppointments: number
  upcomingSubtext: string
}

export async function GET() {
  // Auth
  const auth = await getAuthenticatedUser()
  if (!auth) {
    return Response.json({ error: 'Unauthorized' }, { status: 401 })
  }

  // Rate limit (keyed by user id)
  const { success } = await authedRatelimit.limit(auth.user.authId)
  if (!success) {
    return new Response('Too many requests', {
      status: 429,
      headers: { 'Retry-After': '60' },
    })
  }

  // studioId is derived from the authenticated session — never from the client
  const { studioId } = auth

  try {
    // Sprint 1: real data not yet available (appointments/billing tables added in Sprint 2).
    // Return a typed placeholder so the client hook shape stays stable.
    const response: DashboardKpisResponse = {
      todayBookings: 0,
      todayBookingsSubtext: 'No appointments yet',
      weekRevenue: 0,
      weekRevenueSubtext: 'No revenue yet',
      activeClients: 0,
      activeClientsSubtext: 'No clients yet',
      noShowRate: 0,
      noShowRateSubtext: 'No data yet',
      depositsCollected: 0,
      depositsSubtext: 'No deposits yet',
      upcomingAppointments: 0,
      upcomingSubtext: 'No upcoming appointments',
    }

    logger.info({ studioId }, 'dashboard.kpis.fetched')
    return Response.json(response)
  } catch (err) {
    logger.error({ err, studioId }, 'dashboard.kpis.error')
    return Response.json({ error: 'Failed to fetch KPIs' }, { status: 500 })
  }
}
