'use client'

import { useState, useEffect, useMemo } from 'react'
import { useRouter } from 'next/navigation'
import { Skeleton } from '@/components/ui/skeleton'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { Button } from '@/components/ui/button'
import { AlertCircle, RefreshCw, SearchX, Users } from 'lucide-react'
import { ArtistCard } from '@/components/artists/ArtistCard'
import { ArtistTable } from '@/components/artists/ArtistTable'
import { ArtistListHeader, type ArtistViewMode } from '@/components/artists/ArtistListHeader'
import { ArtistFilterBar, type ArtistFilters } from '@/components/artists/ArtistFilterBar'
import { InviteModal } from '@/components/settings/team/InviteModal'
import type { ArtistCardData } from '@/components/artists/ArtistCard'

const STORAGE_KEY = 'inkos:artists:view'

export default function ArtistsPage() {
  const router = useRouter()
  const [viewMode, setViewMode] = useState<ArtistViewMode>('grid')
  const [artists, setArtists] = useState<ArtistCardData[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [showInviteModal, setShowInviteModal] = useState(false)
  const [filters, setFilters] = useState<ArtistFilters>({
    status: 'all',
    specialty: 'all',
    role: 'all',
  })

  // Persist view mode to localStorage
  useEffect(() => {
    const stored = localStorage.getItem(STORAGE_KEY)
    if (stored === 'grid' || stored === 'table') setViewMode(stored)
  }, [])

  const handleViewModeChange = (mode: ArtistViewMode) => {
    setViewMode(mode)
    localStorage.setItem(STORAGE_KEY, mode)
  }

  const fetchArtists = async () => {
    setLoading(true)
    setError(null)
    try {
      const res = await fetch('/api/artists')
      if (!res.ok) throw new Error('Failed to fetch artists')
      const json = await res.json() as { data: ArtistCardData[] }
      setArtists(json.data ?? [])
    } catch {
      setError('Could not load artists. Please try again.')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    void fetchArtists()
  }, [])

  // All unique specialties across all artists
  const allSpecialties = useMemo(() => {
    const set = new Set<string>()
    artists.forEach((a) => a.specialties.forEach((s) => set.add(s)))
    return [...set].sort()
  }, [artists])

  // Client-side filtering
  const filtered = useMemo(() => {
    return artists.filter((a) => {
      if (filters.status !== 'all' && a.status !== filters.status) return false
      if (filters.specialty !== 'all' && filters.specialty != null && !a.specialties.includes(filters.specialty)) return false
      if (filters.role !== 'all' && a.role !== filters.role) return false
      return true
    })
  }, [artists, filters])

  const hasActiveFilters =
    filters.status !== 'all' || filters.specialty !== 'all' || filters.role !== 'all'

  const clearFilters = () =>
    setFilters({ status: 'all', specialty: 'all', role: 'all' })

  return (
    <div className="flex flex-col min-h-0">
      <ArtistListHeader
        viewMode={viewMode}
        onViewModeChange={handleViewModeChange}
        onAddArtist={() => router.push('/artists/new')}
        onInviteArtist={() => setShowInviteModal(true)}
      />

      <ArtistFilterBar
        filters={filters}
        onFiltersChange={setFilters}
        totalCount={artists.length}
        filteredCount={filtered.length}
        specialties={allSpecialties}
      />

      <div className="flex-1 p-6">
        {/* Error state */}
        {error && !loading && (
          <Alert variant="destructive" className="mb-6">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription className="flex items-center justify-between">
              <span>{error}</span>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => void fetchArtists()}
                className="ml-4 h-7 gap-1.5"
              >
                <RefreshCw className="h-3.5 w-3.5" />
                Retry
              </Button>
            </AlertDescription>
          </Alert>
        )}

        {/* Loading state */}
        {loading && (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
            {Array.from({ length: 8 }).map((_, i) => (
              <Skeleton key={i} className="h-[168px] rounded-xl" />
            ))}
          </div>
        )}

        {/* No artists at all */}
        {!loading && !error && artists.length === 0 && (
          <div className="flex flex-col items-center gap-3 py-16 px-4">
            <Users className="h-10 w-10 text-muted-foreground/40" />
            <p className="text-sm font-semibold">No artists yet</p>
            <p className="text-sm text-muted-foreground text-center max-w-xs">
              Add your first artist or invite them to join your studio.
            </p>
            <div className="flex items-center gap-2 mt-1">
              <Button size="sm" onClick={() => router.push('/artists/new')}>
                + Add Artist
              </Button>
              <Button size="sm" variant="outline" onClick={() => setShowInviteModal(true)}>
                Invite Artist
              </Button>
            </div>
          </div>
        )}

        {/* Filter no-results */}
        {!loading && !error && artists.length > 0 && filtered.length === 0 && hasActiveFilters && (
          <div className="flex flex-col items-center gap-3 py-16 px-4">
            <SearchX className="h-10 w-10 text-muted-foreground/40" />
            <p className="text-sm font-semibold">No artists match</p>
            <p className="text-sm text-muted-foreground text-center max-w-xs">
              Try a different status, specialty, or role filter.
            </p>
            <Button variant="ghost" size="sm" onClick={clearFilters}>
              Clear filters
            </Button>
          </div>
        )}

        {/* Grid view */}
        {!loading && !error && filtered.length > 0 && viewMode === 'grid' && (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
            {filtered.map((artist) => (
              <ArtistCard key={artist.id} artist={artist} />
            ))}
          </div>
        )}

        {/* Table view */}
        {!loading && !error && filtered.length > 0 && viewMode === 'table' && (
          <ArtistTable
            artists={filtered}
            canDeactivate={true}
            onDeactivate={(id) => {
              // Will be wired to real API in team settings item
              void id
            }}
          />
        )}
      </div>

      {/* Invite modal — pre-selects artist role */}
      {showInviteModal && (
        <InviteModal
          open={showInviteModal}
          onOpenChange={setShowInviteModal}
          defaultRole="artist"
          onSuccess={() => {
            setShowInviteModal(false)
            void fetchArtists()
          }}
        />
      )}
    </div>
  )
}
