import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { ClientsPageClient } from './ClientsPageClient'

export const metadata: Metadata = {
  title: 'Clients',
}

export default async function Page() {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()

  // Fetch initial data server-side for fast render
  const [clientsResult, tagsResult] = await Promise.all([
    supabase
      .from('clients')
      .select('id, studio_id, first_name, last_name, email, phone, tags, total_spent_cents, total_sessions, last_visit_at, no_show_count, source, preferred_contact, archived_at, created_at, updated_at, date_of_birth, address, notes, referral_source, cancellation_count, loyalty_points, lifetime_value_cents, avg_session_value_cents, consent_minor')
      .eq('studio_id', auth.studioId)
      .is('archived_at', null)
      .order('last_visit_at', { ascending: false, nullsFirst: false })
      .limit(50),
    supabase
      .from('client_tags')
      .select('id, name, color, icon')
      .eq('studio_id', auth.studioId)
      .order('name'),
  ])

  return (
    <ClientsPageClient
      initialClients={clientsResult.data ?? []}
      tagLibrary={(tagsResult.data ?? []) as Parameters<typeof ClientsPageClient>[0]['tagLibrary']}
    />
  )
}
