async function BillingContent() {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  const supabase = await createClient()

  // Fetch all billing data in parallel
  const [subRpc, summaryRpc, plansResult, invoicesResult] = await Promise.all([
    supabase.rpc('get_studio_subscription', { p_studio_id: auth.studioId }),
    supabase.rpc('get_billing_summary', { p_studio_id: auth.studioId }),
    supabase
      .from('plans')
      .select('id, tier, billing_cycle, display_name, price_cents, currency, max_artists, max_locations, sms_monthly_quota, ai_generations_quota, features, sort_order')
      .eq('is_active', true)
      .order('sort_order', { ascending: true }),
    supabase
      .from('invoices')
      .select('id, dodo_invoice_id, amount_cents, tax_cents, currency, status, period_start, period_end, paid_at, due_date, pdf_url, hosted_url, created_at')
      .eq('studio_id', auth.studioId)
      .order('created_at', { ascending: false })
      .limit(20),
  ])

  const subscriptionParsed = StudioSubscriptionRpcSchema.safeParse(subRpc.data)
  const summaryParsed = BillingSummaryRpcSchema.safeParse(summaryRpc.data)

  if (!subscriptionParsed.success || !summaryParsed.success) {
    // Subscription row may not exist yet for brand-new studios
    return (
      <div className="p-6 max-w-5xl space-y-8">
