export default function TeamPage() {
  const [members, setMembers] = useState<TeamMember[]>([])
  const [invites, setInvites] = useState<TeamInvite[]>([])
  const [currentUserId, setCurrentUserId] = useState('')
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [showInviteModal, setShowInviteModal] = useState(false)

  const fetchData = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const [membersRes, invitesRes, meRes] = await Promise.all([
        fetch('/api/studio-members'),
        fetch('/api/team-invites'),
        fetch('/api/profile'),
      ])

      if (!membersRes.ok) throw new Error('Failed to fetch members')
      const membersJson = await membersRes.json() as { data: TeamMember[] }
      setMembers(membersJson.data ?? [])

      if (invitesRes.ok) {
        const invitesJson = await invitesRes.json() as { data: TeamInvite[] }
        setInvites(invitesJson.data ?? [])
      }

      if (meRes.ok) {
        const meJson = await meRes.json() as { data: { id: string } }
        setCurrentUserId(meJson.data?.id ?? '')
      }
    } catch {
      setError('Could not load team data. Please try again.')
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => { void fetchData() }, [fetchData])

  const pendingCount = invites.filter((i) => i.status === 'pending').length
  const activeCount = members.filter((m) => !m.deactivated_at).length

  return (
    <div className="flex flex-col min-h-0">
      <div className="flex items-center justify-between px-6 py-4 border-b border-border/50">
        <h1 className="text-2xl font-bold tracking-tight">Team &amp; Roles</h1>
        <Button size="sm" onClick={() => setShowInviteModal(true)}>
          + Invite Member
        </Button>
      </div>

      {error && !loading && (
        <div className="p-6">
          <Alert variant="destructive">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription className="flex items-center justify-between">
              <span>{error}</span>
              <Button variant="ghost" size="sm" onClick={() => void fetchData()} className="ml-4 h-7 gap-1.5">
                <RefreshCw className="h-3.5 w-3.5" />
                Retry
              </Button>
            </AlertDescription>
          </Alert>
        </div>
      )}

      <Tabs defaultValue="members" className="mt-0 flex-1">
        <TabsList className="w-full justify-start border-b rounded-none bg-transparent h-auto px-6 gap-0">
          <TabsTrigger
            value="members"
            className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary px-4 pb-3 pt-0 text-sm font-medium"
          >
            Members {!loading && `(${activeCount})`}
          </TabsTrigger>
          <TabsTrigger
            value="invites"
            className="rounded-none border-b-2 border-transparent data-[state=active]:border-primary px-4 pb-3 pt-0 text-sm font-medium"
          >
            Pending Invites {!loading && pendingCount > 0 && `(${pendingCount})`}
          </TabsTrigger>
        </TabsList>

        <TabsContent value="members" className="mt-0 p-6">
          {loading ? (
            <div className="space-y-2">
              {Array.from({ length: 4 }).map((_, i) => (
                <Skeleton key={i} className="h-14 rounded-lg" />
              ))}
            </div>
          ) : (
            <TeamMembersTable
              members={members}
              currentUserId={currentUserId}
              onRefresh={() => void fetchData()}
            />
          )}
        </TabsContent>

        <TabsContent value="invites" className="mt-0 p-6">
          {loading ? (
            <div className="space-y-2">
              {Array.from({ length: 2 }).map((_, i) => (
                <Skeleton key={i} className="h-14 rounded-lg" />
              ))}
            </div>
          ) : (
            <TeamInvitesTable
              invites={invites}
              onRefresh={() => void fetchData()}
            />
          )}
        </TabsContent>
      </Tabs>

      {showInviteModal && (
        <InviteModal
          open={showInviteModal}
          onOpenChange={setShowInviteModal}
          onSuccess={() => void fetchData()}
        />
      )}
    </div>
  )
}

