'use client'

import { useState, useEffect } from 'react'
import Link from 'next/link'
import { CheckCircle2, Circle, X } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

const DISMISS_KEY = 'inkos:getting-started:dismissed'

export interface GettingStartedCounts {
  services: number
  artists: number
  schedules: number
  bookings: number
  bookingPageConfigured: boolean
}

interface Step {
  id: string
  label: string
  description: string
  href: string
  done: boolean
}

function buildSteps(counts: GettingStartedCounts): Step[] {
  return [
    {
      id: 'service',
      label: 'Add your first service',
      description: 'Define what you offer — tattoo styles, consultations, touch-ups.',
      href: '/settings/services',
      done: counts.services > 0,
    },
    {
      id: 'artist',
      label: 'Create your artist profile',
      description: 'Set up your profile so clients can book with you.',
      href: '/artists',
      done: counts.artists > 0,
    },
    {
      id: 'schedule',
      label: 'Set up your availability',
      description: 'Define your working hours so the booking calendar knows when you\'re free.',
      href: '/artists',
      done: counts.schedules > 0,
    },
    {
      id: 'booking',
      label: 'Book your first appointment',
      description: 'Create a booking manually or share your booking link.',
      href: '/appointments/new',
      done: counts.bookings > 0,
    },
    {
      id: 'booking-page',
      label: 'Customize your booking page',
      description: 'Add your studio branding so clients trust the experience.',
      href: '/settings/booking-page',
      done: counts.bookingPageConfigured,
    },
  ]
}

interface GettingStartedCardProps {
  counts: GettingStartedCounts
}

export function GettingStartedCard({ counts }: GettingStartedCardProps) {
  const [dismissed, setDismissed] = useState(false)
  const [mounted, setMounted] = useState(false)

  useEffect(() => {
    setMounted(true)
    if (typeof window !== 'undefined') {
      setDismissed(localStorage.getItem(DISMISS_KEY) === '1')
    }
  }, [])

  const steps = buildSteps(counts)
  const completedCount = steps.filter((s) => s.done).length
  const allDone = completedCount === steps.length

  const handleDismiss = () => {
    localStorage.setItem(DISMISS_KEY, '1')
    setDismissed(true)
  }

  // Hide if dismissed, all done, or not yet mounted (avoids hydration flash)
  if (!mounted || dismissed || allDone) return null

  const progressPct = Math.round((completedCount / steps.length) * 100)

  return (
    <div
      className={cn(
        'relative rounded-xl border border-border/60 bg-card overflow-hidden',
        'before:absolute before:inset-0 before:rounded-xl before:pointer-events-none',
        'before:border before:border-[hsl(var(--color-electric-purple)/0.25)]',
      )}
      style={{
        background:
          'linear-gradient(135deg, hsl(var(--card)) 0%, hsl(var(--color-electric-purple)/0.04) 100%)',
      }}
    >
      {/* Dismiss */}
      <button
        onClick={handleDismiss}
        aria-label="Dismiss getting started checklist"
        className="absolute top-3 right-3 p-1 rounded-md text-muted-foreground hover:text-foreground hover:bg-muted/60 transition-colors"
      >
        <X className="h-4 w-4" />
      </button>

      <div className="px-6 pt-5 pb-6 space-y-4">
        {/* Header */}
        <div>
          <h2 className="text-base font-semibold tracking-tight">Get your studio ready</h2>
          <p className="mt-0.5 text-xs text-muted-foreground">
            Complete these steps to go live — {completedCount}/{steps.length} done
          </p>
        </div>

        {/* Progress bar */}
        <div className="relative h-1.5 w-full rounded-full bg-muted overflow-hidden">
          <div
            className="absolute inset-y-0 left-0 rounded-full transition-all duration-700"
            style={{
              width: `${progressPct}%`,
              background: 'linear-gradient(90deg, hsl(var(--color-electric-purple)) 0%, hsl(var(--primary)) 100%)',
            }}
          />
        </div>

        {/* Steps */}
