import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

export interface DashboardKpisResponse {
  todayBookings: number
  todayBookingsSubtext: string
  weekRevenue: number
  weekRevenueSubtext: string
  activeClients: number
  activeClientsSubtext: string
  noShowRate: number
  noShowRateSubtext: string
  depositsCollected: number
  depositsSubtext: string
  upcomingAppointments: number
  upcomingSubtext: string
}

export async function GET() {
  // Auth
  const auth = await getAuthenticatedUser()
  if (!auth) {
    return Response.json({ error: 'Unauthorized' }, { status: 401 })
  }

  // Rate limit (keyed by user id)
  const { success } = await authedRatelimit.limit(auth.user.authId)
  if (!success) {
    return new Response('Too many requests', {
      status: 429,
      headers: { 'Retry-After': '60' },
    })
  }

  const { studioId } = auth

  try {
    const supabase = await createClient()
    const now = new Date()

    // Start of current week (Monday)
    const dayOfWeek = now.getDay() // 0=Sun
    const diffToMonday = dayOfWeek === 0 ? -6 : 1 - dayOfWeek
    const startOfWeek = new Date(now)
    startOfWeek.setDate(now.getDate() + diffToMonday)
    startOfWeek.setHours(0, 0, 0, 0)

    // Start of current month
    const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1)

    // 30 days ago
    const thirtyDaysAgo = new Date(now)
    thirtyDaysAgo.setDate(now.getDate() - 30)

    // Today bounds
    const todayStart = new Date(now)
    todayStart.setHours(0, 0, 0, 0)
    const todayEnd = new Date(now)
    todayEnd.setHours(23, 59, 59, 999)

    const [
      todayResult,
      weekRevenueResult,
      activeClientsResult,
      noShowResult,
      totalRecentResult,
      depositsResult,
      upcomingResult,
    ] = await Promise.all([
      // Today's bookings (confirmed or in_progress)
      supabase
        .from('bookings')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId)
        .gte('scheduled_at', todayStart.toISOString())
        .lte('scheduled_at', todayEnd.toISOString())
        .in('status', ['confirmed', 'in_progress']),

      // Week revenue — completed bookings
      supabase
        .from('bookings')
        .select('price_cents')
        .eq('studio_id', studioId)
        .eq('status', 'completed')
        .gte('scheduled_at', startOfWeek.toISOString()),

      // Active clients (not archived)
      supabase
        .from('clients')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId)
        .is('archived_at', null),

      // No-shows in last 30 days
      supabase
        .from('bookings')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId)
        .eq('status', 'no_show')
        .gte('scheduled_at', thirtyDaysAgo.toISOString()),

      // Total bookings in last 30 days (for no-show rate denominator)
      supabase
        .from('bookings')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId)
        .gte('scheduled_at', thirtyDaysAgo.toISOString())
        .in('status', ['completed', 'no_show', 'cancelled']),

      // Deposits this month
      supabase
        .from('bookings')
        .select('deposit_cents')
        .eq('studio_id', studioId)
        .eq('deposit_paid', true)
        .gte('created_at', startOfMonth.toISOString()),

      // Upcoming appointments
      supabase
        .from('bookings')
        .select('id', { count: 'exact', head: true })
        .eq('studio_id', studioId)
        .gt('scheduled_at', now.toISOString())
        .in('status', ['pending', 'confirmed']),
    ])

    const todayBookings = todayResult.count ?? 0

    const weekRevenueCents = (weekRevenueResult.data ?? []).reduce(
      (sum, b) => sum + (b.price_cents ?? 0),
      0,
    )
    const weekRevenue = Math.round(weekRevenueCents / 100)

    const activeClients = activeClientsResult.count ?? 0

    const noShowCount = noShowResult.count ?? 0
    const totalRecentCount = totalRecentResult.count ?? 0
    const noShowRate =
      totalRecentCount > 0 ? Math.round((noShowCount / totalRecentCount) * 100) : 0

    const depositsCents = (depositsResult.data ?? []).reduce(
      (sum, b) => sum + (b.deposit_cents ?? 0),
      0,
    )
    const depositsCollected = Math.round(depositsCents / 100)

    const upcomingAppointments = upcomingResult.count ?? 0

    const response: DashboardKpisResponse = {
      todayBookings,
      todayBookingsSubtext:
        todayBookings === 0 ? 'No bookings today' : `${todayBookings} confirmed`,
      weekRevenue,
      weekRevenueSubtext: weekRevenue === 0 ? 'No revenue this week' : 'This week',
      activeClients,
      activeClientsSubtext:
        activeClients === 0 ? 'No clients yet' : `${activeClients} in your database`,
      noShowRate,
      noShowRateSubtext: totalRecentCount === 0 ? 'No data yet' : 'Last 30 days',
      depositsCollected,
      depositsSubtext: depositsCollected === 0 ? 'No deposits this month' : 'This month',
      upcomingAppointments,
      upcomingSubtext:
        upcomingAppointments === 0 ? 'Nothing scheduled' : 'Pending or confirmed',
    }

    logger.info({ studioId }, 'dashboard.kpis.fetched')
    return Response.json(response)
  } catch (err) {
    logger.error({ err, studioId }, 'dashboard.kpis.error')
    return Response.json({ error: 'Failed to fetch KPIs' }, { status: 500 })
  }
}

