import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import type { ActivityEvent, ActivityEventType } from '@/components/shared/ActivityFeed'

function formatTimeAgo(dateStr: string): string {
  const diff = Date.now() - new Date(dateStr).getTime()
  const minutes = Math.floor(diff / 60000)
  if (minutes < 1) return 'just now'
  if (minutes < 60) return `${minutes}m ago`
  const hours = Math.floor(minutes / 60)
  if (hours < 24) return `${hours}h ago`
  const days = Math.floor(hours / 24)
  return `${days}d ago`
}

const ACTION_TYPE_MAP: Record<string, ActivityEventType> = {
  booking_confirmed: 'booking_confirmed',
  booking_cancelled: 'booking_cancelled',
  client_created: 'new_client',
  booking_no_show: 'no_show',
  payment_collected: 'payment_received',
  booking_rescheduled: 'rescheduled',
}

export async function GET() {
  // Auth
  const auth = await getAuthenticatedUser()
  if (!auth) {
    return Response.json({ error: 'Unauthorized' }, { status: 401 })
  }

  // Rate limit
  const { success } = await authedRatelimit.limit(auth.user.authId)
  if (!success) {
    return new Response('Too many requests', {
      status: 429,
      headers: { 'Retry-After': '60' },
    })
  }

  const { studioId } = auth

  try {
    const supabase = await createClient()

    const { data, error } = await supabase
      .from('audit_log')
      .select('id, action, actor_name, target_type, target_name, created_at')
      .eq('studio_id', studioId)
      .order('created_at', { ascending: false })
      .limit(10)

    if (error) {
      logger.error({ err: error, studioId }, 'dashboard.activity.query_error')
      return Response.json({ error: 'Failed to fetch activity' }, { status: 500 })
    }

    const response: ActivityEvent[] = (data ?? []).map((row) => {
      const actionStr = String(row.action ?? '')
      const eventType: ActivityEventType =
        ACTION_TYPE_MAP[actionStr] ?? 'booking_confirmed'
      const actor = String(row.actor_name ?? 'Someone')
      const target = String(row.target_name ?? '')

      let title = actor
      let detail = actionStr.replace(/_/g, ' ')
      if (target) detail += ` — ${target}`

      return {
        id: String(row.id),
        type: eventType,
        title,
        detail,
        timeAgo: formatTimeAgo(String(row.created_at)),
      }
    })

    logger.info({ studioId, count: response.length }, 'dashboard.activity.fetched')
    return Response.json(response)
  } catch (err) {
    logger.error({ err, studioId }, 'dashboard.activity.error')
    return Response.json({ error: 'Failed to fetch activity' }, { status: 500 })
  }
}

