import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { slugify } from '@/lib/utils'

const UpdateServiceSchema = z.object({
  name: z.string().min(1).max(100).optional(),
  description: z.string().max(1000).nullable().optional(),
  duration_min: z.number().int().min(15).max(480).optional(),
  base_price_cents: z.number().int().min(0).optional(),
  deposit_cents: z.number().int().min(0).optional(),
  deposit_required: z.boolean().optional(),
  requires_consultation: z.boolean().optional(),
  is_public: z.boolean().optional(),
  color: z.string().max(20).nullable().optional(),
  sort_order: z.number().int().min(0).optional(),
})

interface RouteContext {
  params: Promise<{ id: string }>
}

export async function PATCH(request: NextRequest, { params }: RouteContext) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { id } = await params

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = UpdateServiceSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  try {
    const supabase = await createClient()

    // Verify ownership
    const { data: existing } = await supabase
      .from('services')
      .select('id, studio_id')
      .eq('id', id)
      .eq('studio_id', authUser.studioId)
      .single()

    if (!existing) {
      return NextResponse.json({ error: 'Service not found' }, { status: 404 })
    }

    const updates: Record<string, unknown> = { ...parsed.data }
    if (parsed.data.name) {
      updates.slug = slugify(parsed.data.name)
    }

    const { data, error } = await supabase
      .from('services')
      .update(updates)
      .eq('id', id)
      .eq('studio_id', authUser.studioId)
      .select()
      .single()

    if (error) {
      logger.error({ err: error, serviceId: id, studioId: authUser.studioId }, 'services update failed')
      return NextResponse.json({ error: 'Failed to update service' }, { status: 500 })
    }

    logger.info({ serviceId: id, studioId: authUser.studioId }, 'services.updated')
    return NextResponse.json({ data })
  } catch (err) {
    logger.error({ err }, 'services PATCH unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function DELETE(_request: NextRequest, { params }: RouteContext) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { id } = await params

  try {
    const supabase = await createClient()

    // Soft-delete: set is_public = false (keeps booking history intact)
    const { error } = await supabase
      .from('services')
      .update({ is_public: false })
      .eq('id', id)
      .eq('studio_id', authUser.studioId)

    if (error) {
      logger.error({ err: error, serviceId: id, studioId: authUser.studioId }, 'services delete failed')
      return NextResponse.json({ error: 'Failed to delete service' }, { status: 500 })
    }

    logger.info({ serviceId: id, studioId: authUser.studioId }, 'services.soft_deleted')
    return new NextResponse(null, { status: 204 })
  } catch (err) {
    logger.error({ err }, 'services DELETE unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { toast } from 'sonner'
import { Plus, Pencil, Trash2, Eye, EyeOff, GripVertical, Loader2, RefreshCw, Package, AlertCircle } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { Switch } from '@/components/ui/switch'
import { Badge } from '@/components/ui/badge'
import { Skeleton } from '@/components/ui/skeleton'
import { Alert, AlertDescription } from '@/components/ui/alert'
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
  SheetFooter,
} from '@/components/ui/sheet'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { formatCurrency } from '@/lib/utils'
import type { Database } from '@/lib/supabase/types'

type Service = Database['public']['Tables']['services']['Row']

// ---------------------------------------------------------------------------
// Form schema
// ---------------------------------------------------------------------------
const ServiceFormSchema = z
  .object({
    name: z.string().min(1, 'Name is required').max(100),
    description: z.string().max(1000).optional(),
    duration_min: z
      .number({ invalid_type_error: 'Enter a number' })
      .int()
      .min(15, 'Minimum 15 minutes')
      .max(480, 'Maximum 8 hours'),
    base_price: z
      .number({ invalid_type_error: 'Enter a price' })
      .min(0, 'Cannot be negative'),
    deposit: z.number().min(0).default(0),
    deposit_required: z.boolean().default(false),
    requires_consultation: z.boolean().default(false),
    is_public: z.boolean().default(true),
    color: z.string().max(20).optional(),
  })
  .refine(
    (d) => !d.deposit_required || d.deposit > 0,
    { message: 'Set a deposit amount when deposit is required', path: ['deposit'] },
  )

type ServiceFormValues = z.infer<typeof ServiceFormSchema>

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
function valuesToPayload(v: ServiceFormValues) {
  return {
    name: v.name,
    description: v.description ?? null,
    duration_min: v.duration_min,
    base_price_cents: Math.round(v.base_price * 100),
    deposit_cents: Math.round(v.deposit * 100),
    deposit_required: v.deposit_required,
    requires_consultation: v.requires_consultation,
    is_public: v.is_public,
    color: v.color ?? null,
  }
}

function serviceToDefaults(s: Service): ServiceFormValues {
  return {
    name: s.name,
    description: s.description ?? '',
    duration_min: s.duration_min,
    base_price: s.base_price_cents / 100,
    deposit: s.deposit_cents / 100,
    deposit_required: s.deposit_required,
    requires_consultation: s.requires_consultation,
    is_public: s.is_public,
    color: s.color ?? '',
  }
}

const EMPTY_DEFAULTS: ServiceFormValues = {
  name: '',
  description: '',
  duration_min: 60,
  base_price: 0,
  deposit: 0,
  deposit_required: false,
  requires_consultation: false,
  is_public: true,
  color: '',
}

// ---------------------------------------------------------------------------
// ServiceForm drawer
// ---------------------------------------------------------------------------
interface ServiceFormSheetProps {
  open: boolean
  editing: Service | null
  onOpenChange: (v: boolean) => void
  onSaved: () => void
}

function ServiceFormSheet({ open, editing, onOpenChange, onSaved }: ServiceFormSheetProps) {
  const isEdit = !!editing
  const [saving, setSaving] = useState(false)

  const {
    register,
    handleSubmit,
    watch,
    setValue,
    reset,
    formState: { errors },
  } = useForm<ServiceFormValues>({
    resolver: zodResolver(ServiceFormSchema),
    defaultValues: EMPTY_DEFAULTS,
  })

  useEffect(() => {
    reset(editing ? serviceToDefaults(editing) : EMPTY_DEFAULTS)
  }, [editing, reset, open])

  const depositRequired = watch('deposit_required')
  const isPublic = watch('is_public')
  const requiresConsultation = watch('requires_consultation')

  const onSubmit = handleSubmit(async (values) => {
    setSaving(true)
    try {
      const payload = valuesToPayload(values)
      const url = isEdit ? `/api/services/${editing.id}` : '/api/services'
      const method = isEdit ? 'PATCH' : 'POST'

      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })

      if (!res.ok) {
        const json = await res.json() as { error?: string }
        throw new Error(json.error ?? 'Failed to save service')
      }

      toast.success(isEdit ? 'Service updated' : 'Service created')
      onOpenChange(false)
      onSaved()
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Something went wrong')
    } finally {
      setSaving(false)
    }
  })

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent side="right" className="w-full sm:max-w-md flex flex-col overflow-hidden p-0">
        <SheetHeader className="px-6 pt-6 pb-4 border-b border-border/40">
          <SheetTitle>{isEdit ? 'Edit Service' : 'New Service'}</SheetTitle>
          <SheetDescription>
            {isEdit ? 'Update the details for this service.' : 'Define a new service for your studio.'}
          </SheetDescription>
        </SheetHeader>

        <form onSubmit={onSubmit} className="flex-1 overflow-y-auto px-6 py-5 space-y-5">
          {/* Name */}
          <div className="space-y-1.5">
            <Label htmlFor="name">Name <span className="text-destructive">*</span></Label>
            <Input
              id="name"
              placeholder="e.g. Full Sleeve Tattoo"
              aria-invalid={!!errors.name}
              {...register('name')}
            />
            {errors.name && (
              <p className="text-xs text-destructive">{errors.name.message}</p>
            )}
          </div>

          {/* Description */}
          <div className="space-y-1.5">
            <Label htmlFor="description">Description</Label>
            <Textarea
              id="description"
              rows={3}
              placeholder="What's included in this service?"
              className="resize-none"
              {...register('description')}
            />
            {errors.description && (
              <p className="text-xs text-destructive">{errors.description.message}</p>
            )}
          </div>

          {/* Duration + Price */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <Label htmlFor="duration">Duration (min) <span className="text-destructive">*</span></Label>
              <Input
                id="duration"
                type="number"
                min={15}
                max={480}
                step={15}
                placeholder="60"
                aria-invalid={!!errors.duration_min}
                {...register('duration_min', { valueAsNumber: true })}
              />
              {errors.duration_min && (
                <p className="text-xs text-destructive">{errors.duration_min.message}</p>
              )}
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="base_price">Base Price ($) <span className="text-destructive">*</span></Label>
              <Input
                id="base_price"
                type="number"
                min={0}
                step={0.01}
                placeholder="150.00"
                aria-invalid={!!errors.base_price}
                {...register('base_price', { valueAsNumber: true })}
              />
              {errors.base_price && (
                <p className="text-xs text-destructive">{errors.base_price.message}</p>
              )}
            </div>
          </div>

          {/* Deposit */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <Label htmlFor="deposit_required" className="cursor-pointer">Require Deposit</Label>
              <Switch
                id="deposit_required"
                checked={depositRequired}
                onCheckedChange={(v) => setValue('deposit_required', v)}
              />
            </div>
            {depositRequired && (
              <div className="space-y-1.5">
                <Label htmlFor="deposit">Deposit Amount ($)</Label>
                <Input
                  id="deposit"
                  type="number"
                  min={0}
                  step={0.01}
                  placeholder="50.00"
                  aria-invalid={!!errors.deposit}
                  {...register('deposit', { valueAsNumber: true })}
                />
                {errors.deposit && (
                  <p className="text-xs text-destructive">{errors.deposit.message}</p>
                )}
              </div>
            )}
          </div>

          {/* Toggles */}
          <div className="space-y-3 border-t border-border/40 pt-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium">Requires Consultation</p>
                <p className="text-xs text-muted-foreground">Client must consult before booking</p>
              </div>
              <Switch
                checked={requiresConsultation}
                onCheckedChange={(v) => setValue('requires_consultation', v)}
              />
            </div>
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium">Visible on Booking Page</p>
                <p className="text-xs text-muted-foreground">Clients can book this service online</p>
              </div>
              <Switch
                checked={isPublic}
                onCheckedChange={(v) => setValue('is_public', v)}
              />
            </div>
          </div>

          {/* Color */}
          <div className="space-y-1.5">
            <Label htmlFor="color">Calendar Color</Label>
            <Input
              id="color"
              placeholder="purple, blue, #7C3AED…"
              maxLength={20}
              {...register('color')}
            />
          </div>
        </form>

        <SheetFooter className="px-6 py-4 border-t border-border/40 flex gap-2">
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={saving} className="flex-1">
            Cancel
          </Button>
          <Button onClick={onSubmit} disabled={saving} className="flex-1">
            {saving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            {isEdit ? 'Save Changes' : 'Create Service'}
          </Button>
        </SheetFooter>
      </SheetContent>
    </Sheet>
  )
}

// ---------------------------------------------------------------------------
// Main page
// ---------------------------------------------------------------------------
export default function ServicesPage() {
  const [services, setServices] = useState<Service[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [sheetOpen, setSheetOpen] = useState(false)
  const [editing, setEditing] = useState<Service | null>(null)
  const [deleteTarget, setDeleteTarget] = useState<Service | null>(null)
  const [deleting, setDeleting] = useState(false)

  const fetchServices = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const res = await fetch('/api/services')
      if (!res.ok) throw new Error('Failed to load services')
      const json = await res.json() as { data: Service[] }
      setServices(json.data ?? [])
    } catch {
      setError('Could not load services. Please try again.')
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    void fetchServices()
  }, [fetchServices])

  const handleDelete = async () => {
    if (!deleteTarget) return
    setDeleting(true)
    try {
      const res = await fetch(`/api/services/${deleteTarget.id}`, { method: 'DELETE' })
      if (!res.ok) throw new Error('Failed to remove service')
      toast.success('Service removed')
      setDeleteTarget(null)
      void fetchServices()
    } catch {
      toast.error('Could not remove service')
    } finally {
      setDeleting(false)
    }
  }

  const openCreate = () => {
    setEditing(null)
    setSheetOpen(true)
  }

  const openEdit = (s: Service) => {
    setEditing(s)
    setSheetOpen(true)
  }

  return (
    <div className="flex flex-col min-h-0">
      {/* Header */}
      <div className="flex items-center justify-between px-6 py-4 border-b border-border/40">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight">Services Catalog</h1>
          <p className="mt-0.5 text-sm text-muted-foreground">
            Define what your studio offers — tattoo styles, consultations, touch-ups
          </p>
        </div>
        <Button size="sm" className="gap-1.5" onClick={openCreate}>
          <Plus className="h-4 w-4" />
          Add Service
        </Button>
      </div>

      <div className="flex-1 overflow-y-auto p-6">
        {/* Error state */}
        {error && !loading && (
          <Alert variant="destructive" className="mb-6">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription className="flex items-center justify-between">
              <span>{error}</span>
              <Button variant="ghost" size="sm" onClick={() => void fetchServices()} className="ml-4 h-7 gap-1.5">
                <RefreshCw className="h-3.5 w-3.5" /> Retry
              </Button>
            </AlertDescription>
          </Alert>
        )}

        {/* Loading */}
        {loading && (
          <div className="space-y-2">
            {Array.from({ length: 4 }).map((_, i) => (
              <Skeleton key={i} className="h-16 rounded-xl" />
            ))}
          </div>
        )}

        {/* Empty state */}
        {!loading && !error && services.length === 0 && (
          <div className="flex flex-col items-center justify-center py-20 gap-3">
            <div className="rounded-xl bg-muted/50 p-4">
              <Package className="h-8 w-8 text-muted-foreground/50" />
            </div>
            <div className="text-center space-y-1">
              <p className="text-sm font-medium">No services yet</p>
              <p className="text-xs text-muted-foreground max-w-xs">
                Add your first service so clients know what you offer and can book online.
              </p>
            </div>
            <Button size="sm" onClick={openCreate} className="gap-1.5 mt-1">
              <Plus className="h-4 w-4" />
              Add First Service
            </Button>
          </div>
        )}

        {/* Services list */}
        {!loading && !error && services.length > 0 && (
          <div className="space-y-2">
            {services.map((service) => (
              <div
                key={service.id}
                className="group flex items-center gap-3 rounded-xl border border-border/50 bg-card px-4 py-3 hover:border-border transition-colors"
              >
                {/* Drag handle placeholder */}
                <GripVertical className="h-4 w-4 text-muted-foreground/30 shrink-0" />

                {/* Color dot */}
                {service.color && (
                  <div
                    className="h-3 w-3 rounded-full shrink-0"
                    style={{ backgroundColor: service.color }}
                  />
                )}

                {/* Info */}
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <p className="text-sm font-medium truncate">{service.name}</p>
                    {!service.is_public && (
                      <Badge variant="secondary" className="text-xs h-5">Hidden</Badge>
                    )}
                    {service.requires_consultation && (
                      <Badge variant="outline" className="text-xs h-5">Consultation</Badge>
                    )}
                  </div>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    {service.duration_min} min &middot;{' '}
                    {formatCurrency(service.base_price_cents)}{' '}
                    {service.deposit_required && service.deposit_cents > 0
                      ? `· ${formatCurrency(service.deposit_cents)} deposit`
                      : ''}
                  </p>
                </div>

                {/* Actions — visible on hover */}
                <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                  <Button
                    variant="ghost"
                    size="icon"
                    className="h-7 w-7"
                    aria-label={service.is_public ? 'Hide service' : 'Show service'}
                    onClick={async () => {
                      try {
                        const res = await fetch(`/api/services/${service.id}`, {
                          method: 'PATCH',
                          headers: { 'Content-Type': 'application/json' },
                          body: JSON.stringify({ is_public: !service.is_public }),
                        })
                        if (!res.ok) throw new Error()
                        toast.success(service.is_public ? 'Service hidden' : 'Service visible')
                        void fetchServices()
                      } catch {
                        toast.error('Failed to update visibility')
                      }
                    }}
                  >
                    {service.is_public ? (
                      <Eye className="h-3.5 w-3.5" />
                    ) : (
                      <EyeOff className="h-3.5 w-3.5" />
                    )}
                  </Button>
                  <Button
                    variant="ghost"
                    size="icon"
                    className="h-7 w-7"
                    aria-label="Edit service"
                    onClick={() => openEdit(service)}
                  >
                    <Pencil className="h-3.5 w-3.5" />
                  </Button>
                  <Button
                    variant="ghost"
                    size="icon"
                    className="h-7 w-7 hover:text-destructive"
                    aria-label="Remove service"
                    onClick={() => setDeleteTarget(service)}
                  >
                    <Trash2 className="h-3.5 w-3.5" />
                  </Button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Create/Edit sheet */}
      <ServiceFormSheet
        open={sheetOpen}
        editing={editing}
        onOpenChange={setSheetOpen}
        onSaved={() => void fetchServices()}
      />

      {/* Delete confirm */}
      <AlertDialog open={!!deleteTarget} onOpenChange={(v) => !v && setDeleteTarget(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Remove {deleteTarget?.name}?</AlertDialogTitle>
            <AlertDialogDescription>
              This will hide the service from your booking page. Existing bookings won&apos;t be affected.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleting}>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              disabled={deleting}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {deleting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Remove
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { toast } from 'sonner'
import { Plus, Pencil, Trash2, Eye, EyeOff, GripVertical, Loader2, RefreshCw, Package, AlertCircle } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { Switch } from '@/components/ui/switch'
import { Badge } from '@/components/ui/badge'
import { Skeleton } from '@/components/ui/skeleton'
import { Alert, AlertDescription } from '@/components/ui/alert'
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
  SheetFooter,
} from '@/components/ui/sheet'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { formatCurrency } from '@/lib/utils'
import type { Database } from '@/lib/supabase/types'

type Service = Database['public']['Tables']['services']['Row']

// ---------------------------------------------------------------------------
// Form schema
// ---------------------------------------------------------------------------
const ServiceFormSchema = z
  .object({
    name: z.string().min(1, 'Name is required').max(100),
    description: z.string().max(1000).optional(),
    duration_min: z
      .number({ invalid_type_error: 'Enter a number' })
      .int()
      .min(15, 'Minimum 15 minutes')
      .max(480, 'Maximum 8 hours'),
    base_price: z
      .number({ invalid_type_error: 'Enter a price' })
      .min(0, 'Cannot be negative'),
    deposit: z.number().min(0).default(0),
    deposit_required: z.boolean().default(false),
    requires_consultation: z.boolean().default(false),
    is_public: z.boolean().default(true),
    color: z.string().max(20).optional(),
  })
  .refine(
    (d) => !d.deposit_required || d.deposit > 0,
    { message: 'Set a deposit amount when deposit is required', path: ['deposit'] },
  )

type ServiceFormValues = z.infer<typeof ServiceFormSchema>

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------
function valuesToPayload(v: ServiceFormValues) {
  return {
    name: v.name,
    description: v.description ?? null,
    duration_min: v.duration_min,
    base_price_cents: Math.round(v.base_price * 100),
    deposit_cents: Math.round(v.deposit * 100),
    deposit_required: v.deposit_required,
    requires_consultation: v.requires_consultation,
    is_public: v.is_public,
    color: v.color ?? null,
  }
}

function serviceToDefaults(s: Service): ServiceFormValues {
  return {
    name: s.name,
    description: s.description ?? '',
    duration_min: s.duration_min,
    base_price: s.base_price_cents / 100,
    deposit: s.deposit_cents / 100,
    deposit_required: s.deposit_required,
    requires_consultation: s.requires_consultation,
    is_public: s.is_public,
    color: s.color ?? '',
  }
}

const EMPTY_DEFAULTS: ServiceFormValues = {
  name: '',
  description: '',
  duration_min: 60,
  base_price: 0,
  deposit: 0,
  deposit_required: false,
  requires_consultation: false,
  is_public: true,
  color: '',
}

// ---------------------------------------------------------------------------
// ServiceForm drawer
// ---------------------------------------------------------------------------
interface ServiceFormSheetProps {
  open: boolean
  editing: Service | null
  onOpenChange: (v: boolean) => void
  onSaved: () => void
}

function ServiceFormSheet({ open, editing, onOpenChange, onSaved }: ServiceFormSheetProps) {
  const isEdit = !!editing
  const [saving, setSaving] = useState(false)

  const {
    register,
    handleSubmit,
    watch,
    setValue,
    reset,
    formState: { errors },
  } = useForm<ServiceFormValues>({
    resolver: zodResolver(ServiceFormSchema),
    defaultValues: EMPTY_DEFAULTS,
  })

  useEffect(() => {
    reset(editing ? serviceToDefaults(editing) : EMPTY_DEFAULTS)
  }, [editing, reset, open])

  const depositRequired = watch('deposit_required')
  const isPublic = watch('is_public')
  const requiresConsultation = watch('requires_consultation')

  const onSubmit = handleSubmit(async (values) => {
    setSaving(true)
    try {
      const payload = valuesToPayload(values)
      const url = isEdit ? `/api/services/${editing.id}` : '/api/services'
      const method = isEdit ? 'PATCH' : 'POST'

      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })

      if (!res.ok) {
        const json = await res.json() as { error?: string }
        throw new Error(json.error ?? 'Failed to save service')
      }

      toast.success(isEdit ? 'Service updated' : 'Service created')
      onOpenChange(false)
      onSaved()
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Something went wrong')
    } finally {
      setSaving(false)
    }
  })

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent side="right" className="w-full sm:max-w-md flex flex-col overflow-hidden p-0">
        <SheetHeader className="px-6 pt-6 pb-4 border-b border-border/40">
          <SheetTitle>{isEdit ? 'Edit Service' : 'New Service'}</SheetTitle>
          <SheetDescription>
            {isEdit ? 'Update the details for this service.' : 'Define a new service for your studio.'}
          </SheetDescription>
        </SheetHeader>

        <form onSubmit={onSubmit} className="flex-1 overflow-y-auto px-6 py-5 space-y-5">
          {/* Name */}
          <div className="space-y-1.5">
            <Label htmlFor="svc-name">Name <span className="text-destructive">*</span></Label>
            <Input
              id="svc-name"
              placeholder="e.g. Full Sleeve Tattoo"
              aria-invalid={!!errors.name}
              {...register('name')}
            />
            {errors.name && (
              <p className="text-xs text-destructive">{errors.name.message}</p>
            )}
          </div>

          {/* Description */}
          <div className="space-y-1.5">
            <Label htmlFor="svc-description">Description</Label>
            <Textarea
              id="svc-description"
              rows={3}
              placeholder="What&apos;s included in this service?"
              className="resize-none"
              {...register('description')}
            />
          </div>

          {/* Duration + Price */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <Label htmlFor="svc-duration">Duration (min) <span className="text-destructive">*</span></Label>
              <Input
                id="svc-duration"
                type="number"
                min={15}
                max={480}
                step={15}
                placeholder="60"
                aria-invalid={!!errors.duration_min}
                {...register('duration_min', { valueAsNumber: true })}
              />
              {errors.duration_min && (
                <p className="text-xs text-destructive">{errors.duration_min.message}</p>
              )}
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="svc-price">Base Price ($) <span className="text-destructive">*</span></Label>
              <Input
                id="svc-price"
                type="number"
                min={0}
                step={0.01}
                placeholder="150.00"
                aria-invalid={!!errors.base_price}
                {...register('base_price', { valueAsNumber: true })}
              />
              {errors.base_price && (
                <p className="text-xs text-destructive">{errors.base_price.message}</p>
              )}
            </div>
          </div>

          {/* Deposit */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <Label htmlFor="svc-deposit-required" className="cursor-pointer">Require Deposit</Label>
              <Switch
                id="svc-deposit-required"
                checked={depositRequired}
                onCheckedChange={(v) => setValue('deposit_required', v)}
              />
            </div>
            {depositRequired && (
              <div className="space-y-1.5">
                <Label htmlFor="svc-deposit">Deposit Amount ($)</Label>
                <Input
                  id="svc-deposit"
                  type="number"
                  min={0}
                  step={0.01}
                  placeholder="50.00"
                  aria-invalid={!!errors.deposit}
                  {...register('deposit', { valueAsNumber: true })}
                />
                {errors.deposit && (
                  <p className="text-xs text-destructive">{errors.deposit.message}</p>
                )}
              </div>
            )}
          </div>

          {/* Toggles */}
          <div className="space-y-3 border-t border-border/40 pt-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium">Requires Consultation</p>
                <p className="text-xs text-muted-foreground">Client must consult before booking</p>
              </div>
              <Switch
                checked={requiresConsultation}
                onCheckedChange={(v) => setValue('requires_consultation', v)}
              />
            </div>
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium">Visible on Booking Page</p>
                <p className="text-xs text-muted-foreground">Clients can book this service online</p>
              </div>
              <Switch
                checked={isPublic}
                onCheckedChange={(v) => setValue('is_public', v)}
              />
            </div>
          </div>

          {/* Color */}
          <div className="space-y-1.5">
            <Label htmlFor="svc-color">Calendar Color</Label>
            <Input
              id="svc-color"
              placeholder="purple, blue, #7C3AED…"
              maxLength={20}
              {...register('color')}
            />
          </div>
        </form>

        <SheetFooter className="px-6 py-4 border-t border-border/40 flex gap-2">
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={saving} className="flex-1">
            Cancel
          </Button>
          <Button onClick={onSubmit} disabled={saving} className="flex-1">
            {saving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            {isEdit ? 'Save Changes' : 'Create Service'}
          </Button>
        </SheetFooter>
      </SheetContent>
    </Sheet>
  )
}

// ---------------------------------------------------------------------------
// Main page
// ---------------------------------------------------------------------------
export default function ServicesPage() {
  const [services, setServices] = useState<Service[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [sheetOpen, setSheetOpen] = useState(false)
  const [editing, setEditing] = useState<Service | null>(null)
  const [deleteTarget, setDeleteTarget] = useState<Service | null>(null)
  const [deleting, setDeleting] = useState(false)

  const fetchServices = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const res = await fetch('/api/services')
      if (!res.ok) throw new Error('Failed to load services')
      const json = await res.json() as { data: Service[] }
      setServices(json.data ?? [])
    } catch {
      setError('Could not load services. Please try again.')
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    void fetchServices()
  }, [fetchServices])

  const handleDelete = async () => {
    if (!deleteTarget) return
    setDeleting(true)
    try {
      const res = await fetch(`/api/services/${deleteTarget.id}`, { method: 'DELETE' })
      if (!res.ok) throw new Error('Failed to remove service')
      toast.success('Service removed')
      setDeleteTarget(null)
      void fetchServices()
    } catch {
      toast.error('Could not remove service')
    } finally {
      setDeleting(false)
    }
  }

  const openCreate = () => {
    setEditing(null)
    setSheetOpen(true)
  }

  const openEdit = (s: Service) => {
    setEditing(s)
    setSheetOpen(true)
  }

  return (
    <div className="flex flex-col min-h-0">
      {/* Header */}
      <div className="flex items-center justify-between px-6 py-4 border-b border-border/40">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight">Services Catalog</h1>
          <p className="mt-0.5 text-sm text-muted-foreground">
            Define what your studio offers — tattoo styles, consultations, touch-ups
          </p>
        </div>
        <Button size="sm" className="gap-1.5" onClick={openCreate}>
          <Plus className="h-4 w-4" />
          Add Service
        </Button>
      </div>

      <div className="flex-1 overflow-y-auto p-6">
        {/* Error state */}
        {error && !loading && (
          <Alert variant="destructive" className="mb-6">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription className="flex items-center justify-between">
              <span>{error}</span>
              <Button variant="ghost" size="sm" onClick={() => void fetchServices()} className="ml-4 h-7 gap-1.5">
                <RefreshCw className="h-3.5 w-3.5" /> Retry
              </Button>
            </AlertDescription>
          </Alert>
        )}

        {/* Loading */}
        {loading && (
          <div className="space-y-2">
            {Array.from({ length: 4 }).map((_, i) => (
              <Skeleton key={i} className="h-16 rounded-xl" />
            ))}
          </div>
        )}

        {/* Empty state */}
        {!loading && !error && services.length === 0 && (
          <div className="flex flex-col items-center justify-center py-20 gap-3">
            <div className="rounded-xl bg-muted/50 p-4">
              <Package className="h-8 w-8 text-muted-foreground/50" />
            </div>
            <div className="text-center space-y-1">
              <p className="text-sm font-medium">No services yet</p>
              <p className="text-xs text-muted-foreground max-w-xs">
                Add your first service so clients know what you offer and can book online.
              </p>
            </div>
            <Button size="sm" onClick={openCreate} className="gap-1.5 mt-1">
              <Plus className="h-4 w-4" />
              Add First Service
            </Button>
          </div>
        )}

        {/* Services list */}
        {!loading && !error && services.length > 0 && (
          <div className="space-y-2">
            {services.map((service) => (
              <div
                key={service.id}
                className="group flex items-center gap-3 rounded-xl border border-border/50 bg-card px-4 py-3 hover:border-border transition-colors"
              >
                <GripVertical className="h-4 w-4 text-muted-foreground/30 shrink-0" />

                {service.color && (
                  <div
                    className="h-3 w-3 rounded-full shrink-0"
                    style={{ backgroundColor: service.color }}
                  />
                )}

                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <p className="text-sm font-medium truncate">{service.name}</p>
                    {!service.is_public && (
                      <Badge variant="secondary" className="text-xs h-5">Hidden</Badge>
                    )}
                    {service.requires_consultation && (
                      <Badge variant="outline" className="text-xs h-5">Consultation</Badge>
                    )}
                  </div>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    {service.duration_min} min &middot;{' '}
                    {formatCurrency(service.base_price_cents)}
                    {service.deposit_required && service.deposit_cents > 0
                      ? ` · ${formatCurrency(service.deposit_cents)} deposit`
                      : ''}
                  </p>
                </div>

                {/* Actions */}
                <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                  <Button
                    variant="ghost"
                    size="icon"
                    className="h-7 w-7"
                    aria-label={service.is_public ? 'Hide service' : 'Show service'}
                    onClick={async () => {
                      try {
                        const res = await fetch(`/api/services/${service.id}`, {
                          method: 'PATCH',
                          headers: { 'Content-Type': 'application/json' },
                          body: JSON.stringify({ is_public: !service.is_public }),
                        })
                        if (!res.ok) throw new Error()
                        toast.success(service.is_public ? 'Service hidden' : 'Service visible')
                        void fetchServices()
                      } catch {
                        toast.error('Failed to update visibility')
                      }
                    }}
                  >
                    {service.is_public ? (
                      <Eye className="h-3.5 w-3.5" />
                    ) : (
                      <EyeOff className="h-3.5 w-3.5" />
                    )}
                  </Button>
                  <Button
                    variant="ghost"
                    size="icon"
                    className="h-7 w-7"
                    aria-label="Edit service"
                    onClick={() => openEdit(service)}
                  >
                    <Pencil className="h-3.5 w-3.5" />
                  </Button>
                  <Button
                    variant="ghost"
                    size="icon"
                    className="h-7 w-7 hover:text-destructive"
                    aria-label="Remove service"
                    onClick={() => setDeleteTarget(service)}
                  >
                    <Trash2 className="h-3.5 w-3.5" />
                  </Button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Create/Edit sheet */}
      <ServiceFormSheet
        open={sheetOpen}
        editing={editing}
        onOpenChange={setSheetOpen}
        onSaved={() => void fetchServices()}
      />

      {/* Delete confirm */}
      <AlertDialog open={!!deleteTarget} onOpenChange={(v) => { if (!v) setDeleteTarget(null) }}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Remove {deleteTarget?.name}?</AlertDialogTitle>
            <AlertDialogDescription>
              This will hide the service from your booking page. Existing bookings won&apos;t be affected.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={deleting}>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              disabled={deleting}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {deleting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Remove
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

